function rawWalk(graphs, choices, entry) {
  const byId=new Map(graphs.map(graph=>[graph.id,graph]));
  let graph=byId.get(entry), node=graph.nodes.find(node=>node.id===graph.root), consumed=0;
  const steps=[], texts=[], visited=new Set();
  for(let budget=0;;++budget){
    assert(budget<1000,'independent raw replay terminates');
    if(node.type==='route'){
      const route=graph.id+'/'+node.id;assert(!visited.has(route),'independent route cycle');visited.add(route);
      graph=byId.get(node.graph);assert(graph,'raw route graph exists');node=graph.nodes.find(node=>node.id===graph.root);continue;
    }
    if(node.type!=='question'||consumed===choices.length)break;
    let answer=choices[consumed], consume=true;
    if(node.id===graph.root && !options(node).some(option=>option.id===answer) && graph.legacyEntryChoices?.[answer]){
      answer=graph.legacyEntryChoices[answer].answer;consume=false;
    }
    const option=options(node).find(option=>option.id===answer);assert(option,'independent raw answer exists');
    const target=node.answers[answer];
    steps.push({graph:graph.id,node:node.id,answer,target});
    texts.push({graph:graph.id,node:node.id,question:node.title,answer,answerLabel:option.label,target});
    node=graph.nodes.find(node=>node.id===target);assert(node,'raw target exists');if(consume)++consumed;
  }
  return {graph:graph.id,node:node.id,type:node.type,title:node.title,techniques:node.techniques??[],steps,texts,consumed};
}
let temporary;
